def permisos_segun_cargo(apps, schema_editor):
    """Los directivos que ya existían reciben los permisos de su cargo (sin cargo: rectoría)."""
    por_cargo = {
        "rector": ["estudiantes", "docentes", "academico", "notas", "cierres", "boletines", "comunicados", "pensiones", "configuracion"],
        "coordinador": ["estudiantes", "docentes", "academico", "notas", "cierres", "boletines", "comunicados"],
        "secretaria": ["estudiantes", "boletines", "comunicados", "pensiones"],
    }
    Usuario = apps.get_model("core", "Usuario")
    for u in Usuario.objects.filter(rol="directivo"):
        if not u.cargo:
            u.cargo = "rector"
        u.permisos = por_cargo.get(u.cargo, por_cargo["rector"])
        u.save(update_fields=["cargo", "permisos"])


